INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: - Hochschuleinrichtungen - Forschungseinrichtungen - Wohnungen für Aufsichts- und Bereitschaftspersone n. Ausnahmsweise können Läden, Schank- und Speisewirtschaften, Anlagen für kulturelle Zwecke und sonstige Wohnungen zugelassen werden." und Textliche Festsetzung 1.2: "Das Sondergebiet Landesvertretung, Hochschule und Forschung dient der Unterbringung einer Landesvertretung sowie Hochschul- und Forschungseinrichtungen. Zulässig sind: - Landesvertretungen - Hochschuleinrichtungen - Forschungseinric','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: n darüber hinaus unter anderem folgende Regelungen getroffen: 1. Textliche Festsetzung 1.1: "Das Sondergebiet Hochschule und Forschung dient vorwiegend der Unterbringung von Hochschul- und Forschungseinrichtungen. Zulässig sind: - Hochschuleinrichtungen - Forschungseinrichtungen - Wohnungen für Aufsichts- und Bereitschaftspersone n. Ausnahmsweise können Läden, Schank- und Speisewirtschaften, Anlagen für kulturelle Zwecke und sonstige Wohnungen zugelassen werden." und Textliche Festsetzung 1.2: "Das Sondergebiet Landesvertretung, Hochschule und Forschung dient der Unterbringung einer Landesvertretung sowie Hochschul- und Forschungseinrichtungen. Zulässig sind: - Landesvertretungen - Hochschuleinrichtungen - Forschungseinrichtungen - Wohnungen für Aufsichts- und Bereitschaftspersone n. Ausnahmsweise können Läden, Schank- und Speisewirtschaften, Anlag','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de//ScansBPlan/Begruendungen/0101206_I-206.pdf#page=13; embedded text offset 28548; sha256 dcd2dc385e8fd823b86a051cfdf