INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: - Landesvertretungen - Hochschuleinrichtungen - Forschungseinrichtungen - Wohnungen für Aufsichts- und Bereitschaftspersone n. Ausnahmsweise können Läden, Schank- und Speisewirtschaften, Anlagen für kulturelle Zwecke und sonstige Wohnungen zugelassen werden." Derzeit ist nicht beabsichtigt, die Landesvertretung des Landes Berlin beim Bund innerhalb der Sondergebietsfläche unterzubringen. Gleichwohl wird aus „Vorsorge und Vorhaltegründen“ insoweit an der beabsichtigten Sondergebietsnutzung festgehalten.','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: hnungen zugelassen werden." und Textliche Festsetzung 1.2: "Das Sondergebiet Landesvertretung, Hochschule und Forschung dient der Unterbringung einer Landesvertretung sowie Hochschul- und Forschungseinrichtungen. Zulässig sind: - Landesvertretungen - Hochschuleinrichtungen - Forschungseinrichtungen - Wohnungen für Aufsichts- und Bereitschaftspersone n. Ausnahmsweise können Läden, Schank- und Speisewirtschaften, Anlagen für kulturelle Zwecke und sonstige Wohnungen zugelassen werden." Derzeit ist nicht beabsichtigt, die Landesvertretung des Landes Berlin beim Bund innerhalb der Sondergebietsfläche unterzubringen. Gleichwohl wird aus „Vorsorge und Vorhaltegründen“ insoweit an der beabsichtigten Sondergebietsnutzung festgehalten. --- page 14 --- 14 Eine anderweitige Nutzung ist nach Maßgabe der sonstigen planungsrechtlichen Zulassungstatbeständen mögli','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de//ScansBPlan/Begruendungen/0101206_I-206.pdf#page=13; embedded text offset 28999; sha256 dcd2dc385e8fd823b86a051