INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','grz',0.8,'Grundflächenzahl von 0,8','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: öchstzulässige Größe der einzelnen Tiefgaragen wird durch die textliche Festsetzung Nr. 3 aber bauflächenbezogen soweit eingeschränkt, dass die in § 19 Abs. 4 der Baunutzungsverordnung vorgegebene Kappungsgrenze einer Grundflächenzahl von 0,8 wei t- gehend eingehalten wird. Durch die Festsetzung von Tiefgaragenflächen außerhalb der überbaubaren Grundstücksflächen wird zugleich der Ausschluss oberirdischer Stellplätze kompensiert. Die allgemeine Zulässigkeit von Nebenanlagen im Sinne von § 14 Ab','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/Begruendungen/0100092ve_1-92VE.pdf#page=60; embedded text offset 189362; sha256 0bdcd16a65b4fd396da1835938918278d6be44f3372d755a3287b0e538391d60' FROM planning_documents d WHERE d.plan_key='1-92VE';
INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','grz',0.8,'Grundflächenzahl von 0,8','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: zulässige Grundfläche durch Garagen und Stellplätze mit ih- ren Zufahrten, Nebenanlagen und bauliche Anlagen unter halb der Geländeoberfläche um bis zu 50 vom Hundert überschritten werden, höchstens jedoch bis zu einer Grundflächenzahl von 0,8. Weite- re Überschreitungen in geringfügigem Ausmaß können zugelassen werden und im Bebauungsplan können auch abweichende Bestimmungen getroffen werden. Da die Baunutzungsverordnung für vorhabenbezogene Bebauungspläne keine verpflichtende An- wendung findet','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/Begruendungen/0100092ve_1-92VE.pdf#page=61; embedded text offset 193295; sha256 0bdcd16a65b4fd396da1835938918278d6be44f3372d755a3287b0e538391d60' FROM planning_documents d WHERE d.plan_key='1-92VE';
INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','grz',0.8,'Grundflächenzahl von 0,8','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: et, werden die Überschreitungsmöglichkeiten im vorhabenbezogenen Bebauungsplan 1-92 VE für jede Baulandfläche explizit textlich festgesetzt. Die im Bauland „Wohnen 1“ insgesamt ermöglichte Grundfläche entspricht einer Grundflächenzahl von 0,8 und kann - in Ergänzung der Hauptbaukörper - durch Nebenanlagen im Sinne des § 14 der Baunutzungsverordnung und baul i- che Anlagen unterhalb der Geländeoberfläche mit ihren Zufahrten, durch die das Baugrundstück lediglich unterbaut wird, in Anspruch genomm','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/Begruendungen/0100092ve_1-92VE.pdf#page=61; embedded text offset 193797; sha256 0bdcd16a65b4fd396da1835938918278d6be44f3372d755a3287b0e538391d60' FROM planning_documents d WHERE d.plan_key='1-92VE';
INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','grz',0.81,'Grundflächenzahl von 0,81','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: ndeoberfläche mit ihren Zufahrten, durch die das Baugrundstück lediglich unterbaut wird, in Anspruch genommen werden. Im Bauland „Wo hnen 2“ entspricht die zulässige Grundfläche bei Unterbauung mit Tiefgaragen einer Grundflächenzahl von 0,81. Im Bau- land „Wohnen 3“ wird zusammen mit spezifischen Überschreitungsmöglichkeiten (siehe unten) ins- gesamt eine Grundfläche von 8.020 m², mithin eine Grundflächenzahl von 0,83 ermöglicht. Eine solche Überschreitungsmöglichkeit ist vor allem notwendig, u','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/Begruendungen/0100092ve_1-92VE.pdf#page=61; embedded text offset 194193; sha256 0bdcd16a65b4fd396da1835938918278d6be44f3372d755a3287b0e538391d60' FROM planning_documents d WHERE d.plan_key='1-92VE';
