INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','gfz',1.2,'Geschossflächenzahl von 1,2','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: Vorhaben soll zusammen mit der im Bebauungsplan 1 -62b geplanten Gebäudestruktur eine Platzfläche begrenzen, die nach den Vorgaben eines Wettbewerbes qualitativ hochwertig ge- staltet werden soll. Die Einhaltung einer Geschossflächenzahl von 1,2 würde an diesem Standort eine städtebauliche Struktur nach sich ziehen, die sich nicht in dieses Konzept einfügt. Die Überschreitung der Obergrenzen, die hier lediglich Orientierungswerte darstellen, ist insofern städtebaulich begründet. Ausgleichend','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/Begruendungen/0100093ve_1-93VE.pdf#page=53; embedded text offset 167924; sha256 eab00d1c4785a580a2cd1d6bc0392a9a2dc56ea233655ca12272cfc7cf28de88' FROM planning_documents d WHERE d.plan_key='1-93VE';
