INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: - Einrichtungen des Deutschen Bundestages, - Anlagen und Einrichtungen der Gebäudetechnik. 2. Maß der baulichen Nutzung 2.1 Als zulässige Grundfläche wird in den Sondergebiete n mit der Zweckbestimmung Bundestag / Besucher- und Informationszentrum (SO 1 .1 und SO 1.2) die im zeichnerischen Teil festgesetzte überbaubare Grundstücksfläche festgesetzt. 2.2 Auf der Fläche des Sondergebietes mit der Zwec kbestimmung Bundestag / Besucher - und Informationszentrum (SO 1.1) darf die zulässige Grundfläche durch','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: ges, - Technische Einrichtungen und Anlagen und Leitungen. 1.3 Das Sondergebiet mit der Zweckbestimmung Bundes tag (SO 2) dient vorwiegend der Unterbringung von Einrichtungen und Anlagen des Deu tschen Bundestages. Zulässig sind: - Einrichtungen des Deutschen Bundestages, - Anlagen und Einrichtungen der Gebäudetechnik. 2. Maß der baulichen Nutzung 2.1 Als zulässige Grundfläche wird in den Sondergebiete n mit der Zweckbestimmung Bundestag / Besucher- und Informationszentrum (SO 1 .1 und SO 1.2) die im zeichnerischen Teil festgesetzte überbaubare Grundstücksfläche festgesetzt. 2.2 Auf der Fläche des Sondergebietes mit der Zwec kbestimmung Bundestag / Besucher - und Informationszentrum (SO 1.1) darf die zulässige Grundfläche durch die Grundflächen von Nebenanlagen im Sinne des § 14 der Baunutzungsveror dnung und baulichen Anlagen unterhalb der Geländeober','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/01_MI/1-94_Abz.pdf#page=1; embedded text offset 15943; sha256 4f863c4c4ff1b73ca1795c761ba7bf46ae