INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','grz',0.87,'Grundflächenzahl von 0,87','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: tsetzung vorgesehen. Sowohl für das SO 1.1 wie auch für das SO 2 wird eine erwartet, weshalb gere- gelt wird, dass eine Überschreitung durch entsprechende bauliche Anlagen unterhalb der Gelän- deoberfläche bis zu einer Grundflächenzahl von 0,87 zulässig ist. Aufgrund dessen, dass die ge- plante S-Bahntrasse 21 das SO 2 quert, wir dieses im Korridor der geplanten Trasse hinsichtlich der Tiefe der Unterbaubarkeit begrenzt, um Beeinträchtigungen der beiden Baumaßnahmen zu verhindern. Neben den Fests','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/01_MI/1-94_Begr.pdf#page=147; embedded text offset 360288; sha256 19ab3f135ec0f9c709b4836f2f00307f2d4fdb37c6c1c5dfd8e535510a39a4bd' FROM planning_documents d WHERE d.plan_key='1-94';
