INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: - Einrichtungen zur Besucherinformation, - Läden, Schank- und Speisewirtschaften, - Einrichtungen für die Sicherheitskontrollen, - Öffentliche Toilettenanlagen innerhalb der Fläche T. Rechtsgrundlage: § 9 Abs. 1 Nr. 1 BauGB i. V. m. §§ 11 Abs. 2, 16 Abs. 2 Nr. 2 und Nr. 3 BauNVO. Durch den Abbruch des Reichstag-Pavillons entfallen öffentliche Toiletten, die nach Abstimmung zwischen dem Land Berlin und dem Nutzer ersetzt werden sollen. Diese Toilettenanlage soll auch von nicht angemeldeten Besuchenden','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: und Informationszentrum (SO 1.1) dient vorwiegend der Unterbringung eines Besucher- und Informationszentrums für den Deutschen Bundestag sowie der unmittelbar damit verbundenen Nutzungen, Anlagen und Einrich- tungen. Zulässig sind: - Einrichtungen zur Besucherinformation, - Läden, Schank- und Speisewirtschaften, - Einrichtungen für die Sicherheitskontrollen, - Öffentliche Toilettenanlagen innerhalb der Fläche T. Rechtsgrundlage: § 9 Abs. 1 Nr. 1 BauGB i. V. m. §§ 11 Abs. 2, 16 Abs. 2 Nr. 2 und Nr. 3 BauNVO. Durch den Abbruch des Reichstag-Pavillons entfallen öffentliche Toiletten, die nach Abstimmung zwischen dem Land Berlin und dem Nutzer ersetzt werden sollen. Diese Toilettenanlage soll auch von nicht angemeldeten Besuchenden genutzt werden können und ist öffentlich zugänglich. Dies wird in einer städtebaulichen Vereinbarung zwischen dem Land Berlin und','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/01_MI/1-94_Begr.pdf#page=150; embedded text offset 366681; sha256 19ab3f135ec0f9c709b4836f2f003