INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: - Einrichtungen zur Besucherinformation, - Fußgängertunnel für die Abgeordneten, Bediensteten und Besucher des Deutschen Bundesta- ges, - Technische Einrichtungen und Anlagen und Leitungen. Rechtsgrundlage: § 9 Abs. 1 Nr. 1 BauGB i. V. m. §§ 11 Abs. 2 BauNVO. Die Abgrenzung des Sondergebiets SO 1.2 entspricht der Projektplanung für das Tunnelbauwerk des BIZ. Es wurde dergestalt an die Vorhabenplanung angepasst, dass bauliche Anlagen unter- halb der Geländeoberfläche entlang der nördlichen Grenze des Sonderg','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: t vorwiegend der Unterbringung eines Fußgängertunnels für die Abgeordneten, Be- diensteten und Besucher des Deutschen Bundestages sowie technischer Einrichtungen und Anla- gen und Leitungen zwischen SO 1.1 und dem SO 2. Zulässig sind: - Einrichtungen zur Besucherinformation, - Fußgängertunnel für die Abgeordneten, Bediensteten und Besucher des Deutschen Bundesta- ges, - Technische Einrichtungen und Anlagen und Leitungen. Rechtsgrundlage: § 9 Abs. 1 Nr. 1 BauGB i. V. m. §§ 11 Abs. 2 BauNVO. Die Abgrenzung des Sondergebiets SO 1.2 entspricht der Projektplanung für das Tunnelbauwerk des BIZ. Es wurde dergestalt an die Vorhabenplanung angepasst, dass bauliche Anlagen unter- halb der Geländeoberfläche entlang der nördlichen Grenze des Sondergebietes SO 1.2 im An- schluss an das Sondergebiet SO 2 einbezogen worden sind. Textliche Festsetzung Nr. 1.3 Das Sondergebiet','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/01_MI/1-94_Begr.pdf#page=151; embedded text offset 369514; sha256 19ab3f135ec0f9c70