INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: - Einrichtungen des Deutschen Bundestages, - Anlagen und Einrichtungen der Gebäudetechnik. Rechtsgrundlage: § 9 Abs. 1 Nr. 1 BauGB i. V. m. § 11 Abs. 2 BauNVO Für die Vorfahrt des RTG, in deren Bereich das Ende des Verbindungstunnels zwischen BIZ und RTG vorgesehen ist, sieht der Bebauungsplan 1-94 unter Einbeziehung der Freitreppe sowie ei- nes Teils des Platzes der Republik die Ausweisung eines Sondergebiets mit der Zweckbestim- mung Bundestag (Sondergebiet SO 2 ) vor und überplant somit in dies','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: iet SO 2 einbezogen worden sind. Textliche Festsetzung Nr. 1.3 Das Sondergebiet mit der Zweckbestimmung Bundestag (SO 2) dient vorwiegend der Unterbrin- gung von Einrichtungen und Anlagen des Deutschen Bundestages. Zulässig sind: - Einrichtungen des Deutschen Bundestages, - Anlagen und Einrichtungen der Gebäudetechnik. Rechtsgrundlage: § 9 Abs. 1 Nr. 1 BauGB i. V. m. § 11 Abs. 2 BauNVO Für die Vorfahrt des RTG, in deren Bereich das Ende des Verbindungstunnels zwischen BIZ und RTG vorgesehen ist, sieht der Bebauungsplan 1-94 unter Einbeziehung der Freitreppe sowie ei- nes Teils des Platzes der Republik die Ausweisung eines Sondergebiets mit der Zweckbestim- mung Bundestag (Sondergebiet SO 2 ) vor und überplant somit in diesem Bereich die Festset- zungen des Bebauungsplans II 200d. Im Bereich der Freitreppe endet der Besuchertunnel und führt auf den','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/01_MI/1-94_Begr.pdf#page=151; embedded text offset 370314; sha256 19ab3f135ec0f9c709b4836f2f00307f2d4fdb37