INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: - Büro- und Veranstaltungsräume - Logistikgebäude - weitere, dem Bundeskanzleramt dienende Anlagen und Einrichtungen. Dienstwohnungen, Schank- und Speisewirtschaften sowie Anlagen f ür kulturelle und soziale Zwecke können ausnahmsweise zugelassen werden. 2. Maß der baulichen Nutzung 2.1 In den Sondergebieten SO 3 und SO 4 wird als zulässige Grundfläche die im zeichnerischen Teil festgesetzte überbaubare Grundstücksfläche festgesetzt. 2.2 In den Sondergebieten SO 1 und SO 2 können ausna','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: a r t e n M o a b i t T i e r g a r t e n Textliche Festsetzungen 1. Art der baulichen Nutzung 1.1 Die Sondergebiete „Bundeskanzler amt“ dienen vorwiegend der Unte rbringung von Einrichtungen des Bundeskanzleramtes. Zulässig sind: - Büro- und Veranstaltungsräume - Logistikgebäude - weitere, dem Bundeskanzleramt dienende Anlagen und Einrichtungen. Dienstwohnungen, Schank- und Speisewirtschaften sowie Anlagen f ür kulturelle und soziale Zwecke können ausnahmsweise zugelassen werden. 2. Maß der baulichen Nutzung 2.1 In den Sondergebieten SO 3 und SO 4 wird als zulässige Grundfläche die im zeichnerischen Teil festgesetzte überbaubare Grundstücksfläche festgesetzt. 2.2 In den Sondergebieten SO 1 und SO 2 können ausnahmsweise technische Dachaufbauten wie Anlagen zum Betrieb eines Hubsc hrauberlandeplatzes, Schornsteine, Lüftungsanlagen, Solara','embedded_text_mention','low','unreviewed',d.source_id,'https://mitte.gis-broker.de/bplaene/0100106.pdf#page=1; embedded text offset 2875; sha256 fa76a583dada0ae3d2aacf29a6ee899ae7997cd286005502fb8bd7df2fda5e42' FROM planning_documents d WHERE d.plan_key='1-106';
INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','grz',0.4,'Grundflächenzahl von 0,4','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: ten Fläche des geplanten Post- und Logistikbereichs ent- spricht hingegen nicht dem geltendem Planungsrecht. Nach den Festsetzungen des Bebauungs- plans II-200g ist hier eine Nutzung als allgemeines Wohngebiet mit einer Grundflächenzahl von 0,4 zulässig. Unter Berücksichtigung der Überschreitungsregelung nach § 19 Abs. 4 BauNVO wäre die Versiegelung von 60 % der Grundstücksfläche unter Verlust des Pionierwalds zulässig. Eine Aus- nutzung dieses Baurechts in absehbarer Zeit wäre angesichts des hohe','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/Begruendungen/0100106_1-106.pdf#page=52; embedded text offset 165858; sha256 2f661f0262086d13cf8d717942b13a4bb2c9db0b8c1de5dea311a7baf63bb982' FROM planning_documents d WHERE d.plan_key='1-106';
