INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: 1.1 Anlagen für kulturelle Zwecke und Konferenzen 1.2 Bildungs- und Forschungseinrichtungen 1.3 Läden, Schank- und Speisewirtschaften, soweit sie im Umfang der Zweckbestimmung untergeordnet sind, 1.4 Werkstätten, die im Zusammenhang mit der Zweckbest immung stehen 1.5 Büro- und Verwaltungsflächen, die der Zweckbesti mmung dienen. Ausnahmsweise sind auf der Fläche KLMNK oberhalb von 65, 0 m über NHN nur Schank- und Speisewirtschaften zulässig. (Rechtsgrundlage: § 9 Abs. 1 Nr. 1 und Abs. 3 BauGB i.','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: .3 Textliche Festsetzungen 1. Das sonstige Sondergebiet mit der Zweckbestimmung Kul tur, Bildung und Forschung dient vorwiegend der Unterbringung kultureller Einrichtungen und Bildungs- und Forschungseinrichtungen. Zulässig sind: 1.1 Anlagen für kulturelle Zwecke und Konferenzen 1.2 Bildungs- und Forschungseinrichtungen 1.3 Läden, Schank- und Speisewirtschaften, soweit sie im Umfang der Zweckbestimmung untergeordnet sind, 1.4 Werkstätten, die im Zusammenhang mit der Zweckbest immung stehen 1.5 Büro- und Verwaltungsflächen, die der Zweckbesti mmung dienen. Ausnahmsweise sind auf der Fläche KLMNK oberhalb von 65, 0 m über NHN nur Schank- und Speisewirtschaften zulässig. (Rechtsgrundlage: § 9 Abs. 1 Nr. 1 und Abs. 3 BauGB i. V. mit § 11 Abs. 2 BauNVO) Die geplante textliche Festsetzung regelt auf der Grun dlage des geplanten Nutzungskonzepts die im s','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de//ScansBPlan/Begruendungen/0101219_I-219.pdf#page=38; embedded text offset 130427; sha256 beda0e401b613159ef8cbae20a9c8