INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','gfz',1.2,'Geschossflächenzahl von 1,2','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: Obergrenzen nach § 17 BauNVO im Vorhabenbereich eine Leitlinien- und Orientierungsfunktion zu. Der Bebauungsplan ermöglicht für den Vorhabenbereich „Wohngebäude“ eine deutliche Überschreitung der Obergrenze für die Geschossflächenzahl von 1,2 gemäß § 17 BauNVO bis auf 1,94. Auf die einzelnen Baufelder bezogen ergeben sich folgende Geschossfläche n- zahlen: Baufeld A: 1,86 Baufeld B: 1,62 Baufeld C: 2,01 Baufeld D: 2,14 Baufeld E: 2,26. Nach Maßgabe von § 17 Abs. 2 Satz 1 BauNVO ist ei','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/Begruendungen/0100064aVE_1-64aVE.pdf#page=218; embedded text offset 655338; sha256 70a4ebd514161a7fe9169f4262a27e38737297f341c4da1d1808f208f64280d5' FROM planning_documents d WHERE d.plan_key='1-64aVE';
INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: a) Wohngebäude; b) im ersten und zweiten Vollgeschoss der Wohngebäude Räume für freie Berufe und solche Gewerbetreibende, die ihren Beruf in ähnlicher Art ausüben; --- page 74 --- Vorhabenbezogener Bebauungsplan 1-64a VE Begründung 74 c) innerhalb der Fläche A4A5A6A7A8A9A4 in Gebäudeteilen unterhalb von 49,0 m über NHN sowie innerhalb der Flächen B1B2B14B13B1, C17C18C19C20C21C22C23C24C17 und D7D8D9D10D11D12D7 im ersten Vollgeschoss der Wohngebäude auch - die der Versorgung des Gebiets dienende Läden','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: bs. 3 Satz 2 BauGB zulässig. III.3.2.1 Vorhabenbereich mit der Bezeichnung „Wohngebäude“ Textliche Festsetzung 1: (1) Der Vorhabenbereich mit der Bezeichnung „Wohngebäude“ dient vorwiegend dem Wohnen. (2) Zulässig sind: a) Wohngebäude; b) im ersten und zweiten Vollgeschoss der Wohngebäude Räume für freie Berufe und solche Gewerbetreibende, die ihren Beruf in ähnlicher Art ausüben; --- page 74 --- Vorhabenbezogener Bebauungsplan 1-64a VE Begründung 74 c) innerhalb der Fläche A4A5A6A7A8A9A4 in Gebäudeteilen unterhalb von 49,0 m über NHN sowie innerhalb der Flächen B1B2B14B13B1, C17C18C19C20C21C22C23C24C17 und D7D8D9D10D11D12D7 im ersten Vollgeschoss der Wohngebäude auch - die der Versorgung des Gebiets dienende Läden, Schank- und Speisewirtschaften und nicht störende Handwerksbetriebe, - Anlagen für Verwaltungen, - kirchliche, kulturel','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/Begruendungen/0100064aVE_1-64aVE.pdf#page=73; embedded text offset 203560; sha256 70a4ebd514161a7fe9169f4262a27e38737297f341c4da1d1808f208f64280d5' FROM planning_documents d WHERE d.plan_key='1-64aVE';
INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: a) Gebäude zur Unterbringung von Betreuungseinrichtungen für Kinder; b) nicht mehr als 5 oberirdische Stellplätze für den durch die zugelassene Nutzung verursachten Bedarf, sowie die dazu erforderlichen Zufahrten; c) Nebenanlagen im Sinne von § 14 Absatz 1 der Baunutzungsverordnung. (3) Ausnahmsweise können die der Ver - und Entsorgung des Vorhabenbereichs di e- nenden Nebenanlagen im Sinne von § 14 Absatz 2 der Baunutzungsverordnung zug e- lassen werden. Die Fläche für eine Kinderbetreuungseinr','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: 80 III.3.2.2 Vorhabenbereich mit der Bezeichnung „Kindertagesstätte“ Textliche Festsetzung 2: (1) Der Vorhabenbereich mit der Bezeichnung „Kindertagesstätte" dient der Errichtung einer Kindertagesstätte. (2) Zulässig sind: a) Gebäude zur Unterbringung von Betreuungseinrichtungen für Kinder; b) nicht mehr als 5 oberirdische Stellplätze für den durch die zugelassene Nutzung verursachten Bedarf, sowie die dazu erforderlichen Zufahrten; c) Nebenanlagen im Sinne von § 14 Absatz 1 der Baunutzungsverordnung. (3) Ausnahmsweise können die der Ver - und Entsorgung des Vorhabenbereichs di e- nenden Nebenanlagen im Sinne von § 14 Absatz 2 der Baunutzungsverordnung zug e- lassen werden. Die Fläche für eine Kinderbetreuungseinrichtung wird als Vorhabenbereich mit der Bezeic h- nung „Kindertagesstätte“ festgesetzt. Gemäß textlicher Festsetzung Nr. 2 (2) s','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/Begruendungen/0100064aVE_1-64aVE.pdf#page=80; embedded text offset 223973; sha256 70a4ebd514161a7fe9169f4262a27e38737297f341c4da1d1808f208f64280d5' FROM planning_documents d WHERE d.plan_key='1-64aVE';
