INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','grz',0.6,'Grundflächenzahl von 0,6','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: ungsverfahrens für die Besti m- mung des zulässigen Maßes der baulichen Nutzung die Vorschriften des § 34 Abs. 1 BauGB heranzuziehen. Demnach wäre eine kulturelle Nutzung westlich der Neuen Nati o- nalgalerie mit einer Grundflächenzahl von 0,6 für Hauptanlagen und einem Gesamtversi e- gelungsgrad von 0,8 zulässig . Ein Ausgleich ist für diese Fläche daher auf Grundlage von § 1a Abs. 3 Satz 6 BauGB nicht erforderlich. Im Gegensatz dazu ist auf der Fläche nördlich der Sigismundstraße auf der Grund','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de/ScansBPlan/Begruendungen/0100035ba_1-35ba.pdf#page=300; embedded text offset 733494; sha256 8a782cb4eaa3822265d191805c04e3a2657a76f067e17314388b0efb9002a1e9' FROM planning_documents d WHERE d.plan_key='1-35ba';
