INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','other',NULL,'Zulässig sind: Ausnahmsweise können zugelassen werden: 1. Läden, Schank- und Speisewirtschaften. 1. Büro- und Verwaltungsnutzungen, 1.2 1.3 2. Anlagen für kulturelle und soziale Zwecke, 3. Gästewohnungen der Bundesregierung. Mischgebiete (MI 1 und MI 2) In den Mischgebieten MI 1 und MI 2 sind Tankstellen und Gartenbaubetriebe nicht zulässig.1.1 1,0 m vor die Baulinie ausnahmsweise zugelassen werden. Im MI 2 kann entlang der Planstraße A im 2. bis 4. Vollgeschoss auf 30 vom Hundert der Fassadenfläche ein Vortret','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: d Städtebau und der Unterbringung von kulturellen Einrichtungen. Sondergebiet Bundesregierung (SO Bundesregierung) Das Sondergebiet Bundesregierung dient vorwiegend der Unterbringung von Nutzungen der Bundesregierung. Zulässig sind: Ausnahmsweise können zugelassen werden: 1. Läden, Schank- und Speisewirtschaften. 1. Büro- und Verwaltungsnutzungen, 1.2 1.3 2. Anlagen für kulturelle und soziale Zwecke, 3. Gästewohnungen der Bundesregierung. Mischgebiete (MI 1 und MI 2) In den Mischgebieten MI 1 und MI 2 sind Tankstellen und Gartenbaubetriebe nicht zulässig.1.1 1,0 m vor die Baulinie ausnahmsweise zugelassen werden. Im MI 2 kann entlang der Planstraße A im 2. bis 4. Vollgeschoss auf 30 vom Hundert der Fassadenfläche ein Vortreten von Gebäudeteilen und zwar für Erker und Balkone bis zu bauten wie Schornsteine und Lüftungsanlagen ist nicht zulässig. Im MI 2','embedded_text_mention','low','unreviewed',d.source_id,'https://mitte.gis-broker.de/bplaene/0101208.pdf#page=1; embedded text offset 9606; sha256 36de913a7cbdba05d3507a6f8b305aa64d035664f3de0423a038992619dd4142' FROM planning_documents d WHERE d.plan_key='I-208';
