INSERT INTO planning_rules (document_id,zone_id,applicability,rule_type,numeric_value,text_value,interpretation,extraction_method,confidence,review_status,source_id,source_locator) SELECT d.id,NULL,'document_summary','building_form',NULL,'closed','Machine-readable document mention only; it may describe a subarea, exception, auxiliary coverage, rationale scenario, legend, or OCR error. It is not a parcel-specific rule. Context: chaft beherrschen. Die Stadtkante entlang Spree, Tiergarten und Stadtbahnviadukt ist dabei besonders gefährdet. 2.4 Bauweise Für alle Baugebiete – mit Ausnahme des Kerngebietes nördlich der Reinhardtstraße - wird geschlossene Bauweise festgesetzt. Dies dient in er ster Linie dazu, geschlossene Gebäudefronten als klare Begrenzung der Straßenräum e zu erhalten, insbesondere wenn die Blöcke in mehrere Grundstücke unterteilt sind oder werden. Da in den Baugebieten ausnahmsweise auch Wohnungen zulässig','embedded_text_mention','low','unreviewed',d.source_id,'https://fbinter.stadt-berlin.de//ScansBPlan/Begruendungen/0101210_I-210.pdf#page=19; embedded text offset 37500; sha256 1563d0d4706dfdf66f554a6c36465214d587c202bab61416181e2c4abb5f2ada' FROM planning_documents d WHERE d.plan_key='I-210';
